package main

import (
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

// LedgerRec – 01 LEDGER-REC, 14 bytes
type LedgerRec struct {
	BrBranch string          // PIC X(2) @0 len=2
	BrAcct   string          // PIC X(4) @2 len=4
	BrType   string          // PIC X(1) @6 len=1
	BrAmt    decimal.Decimal // PIC 9(5)V99 @7 len=7
}

// Working-storage
var WsEofFlag string = "N"
var WsFirstFlag string = "Y"
var WsPrevBranch string = "  "
var WsPrevAcct string = "    "
var WsBal decimal.Decimal = decimal.Zero
var WsBranchTot decimal.Decimal = decimal.Zero
var WsGrandTot decimal.Decimal = decimal.Zero
var WsSkipped int64 = 0
var WsAmtEd string
var WsBalEd string
var WsTotEd string

var CurRec LedgerRec
var inputLines []string
var curIdx int

func InputDone() bool  { return WsEofFlag == "Y" }
func FirstRecord() bool { return WsFirstFlag == "Y" }

func pow10Int64(n int) int64 {
	p := int64(1)
	for i := 0; i < n; i++ {
		p *= 10
	}
	return p
}

func storeField(v decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	vTrunc := v.Truncate(int32(scale))
	if vTrunc.IsZero() {
		return decimal.Zero
	}
	scaled := vTrunc.Shift(int32(scale)).Truncate(0)
	scaledInt := scaled.IntPart()
	neg := scaledInt < 0
	absScaled := scaledInt
	if absScaled < 0 {
		absScaled = -absScaled
	}
	scalePow := pow10Int64(scale)
	var absIntPart, absFracPart int64
	if scale > 0 {
		absIntPart = absScaled / scalePow
		absFracPart = absScaled % scalePow
	} else {
		absIntPart = absScaled
		absFracPart = 0
	}
	modPow := pow10Int64(intDigits)
	absIntPart = absIntPart % modPow
	newAbsScaled := absIntPart*scalePow + absFracPart
	if newAbsScaled == 0 {
		return decimal.Zero
	}
	res := decimal.New(newAbsScaled, int32(-scale))
	if neg {
		res = res.Neg()
	}
	return res
}

func formatEdited(v decimal.Decimal, picture string) string {
	signPresent := false
	signChar := byte(' ')
	picBody := picture
	if len(picture) > 0 && (picture[0] == '-' || picture[0] == '+') {
		signPresent = true
		if v.IsNegative() && !v.IsZero() {
			signChar = '-'
		} else {
			signChar = ' '
		}
		picBody = picture[1:]
		v = v.Abs()
	} else {
		// unsigned – show absolute
		if v.IsNegative() {
			v = v.Abs()
		}
	}
	dotIdx := strings.Index(picBody, ".")
	var beforeDotPic, afterDotPic string
	scale := 0
	if dotIdx >= 0 {
		beforeDotPic = picBody[:dotIdx]
		afterDotPic = picBody[dotIdx+1:]
		scale = len(afterDotPic)
	} else {
		beforeDotPic = picBody
		scale = 0
	}
	intDigits := 0
	for _, ch := range beforeDotPic {
		if ch == 'Z' || ch == '9' {
			intDigits++
		}
	}

	scaled := v.Shift(int32(scale)).Truncate(0)
	scaledInt := scaled.IntPart()
	if scaledInt < 0 {
		scaledInt = -scaledInt
	}
	scalePow := pow10Int64(scale)
	var intPart, fracPart int64
	if scale > 0 {
		intPart = scaledInt / scalePow
		fracPart = scaledInt % scalePow
	} else {
		intPart = scaledInt
		fracPart = 0
	}
	if intDigits > 0 {
		intPart = intPart % pow10Int64(intDigits)
	}
	intStr := fmt.Sprintf("%0*d", intDigits, intPart)
	fracStr := ""
	if scale > 0 {
		fracStr = fmt.Sprintf("%0*d", scale, fracPart)
	}
	// build before dot
	outBefore := make([]byte, 0, len(beforeDotPic))
	suppressed := true
	digitIdx := 0
	for i := 0; i < len(beforeDotPic); i++ {
		c := beforeDotPic[i]
		if c == ',' {
			if suppressed {
				outBefore = append(outBefore, ' ')
			} else {
				outBefore = append(outBefore, ',')
			}
		} else if c == 'Z' || c == '9' {
			d := intStr[digitIdx]
			digitIdx++
			if c == 'Z' {
				if suppressed && d == '0' {
					outBefore = append(outBefore, ' ')
				} else {
					outBefore = append(outBefore, d)
					suppressed = false
				}
			} else { // '9'
				outBefore = append(outBefore, d)
				suppressed = false
			}
		} else {
			outBefore = append(outBefore, c)
		}
	}
	var result string
	if signPresent {
		result = string([]byte{signChar}) + string(outBefore)
	} else {
		result = string(outBefore)
	}
	if scale > 0 {
		result += "." + fracStr
	}
	return result
}

func formatAmtEd(v decimal.Decimal) string { return formatEdited(v, "ZZ,ZZ9.99") }
func formatBalEd(v decimal.Decimal) string { return formatEdited(v, "-Z,ZZZ,ZZ9.99") }
func formatTotEd(v decimal.Decimal) string { return formatEdited(v, "-ZZZ,ZZZ,ZZ9.99") }

func displayConcat(parts ...string) {
	s := strings.Join(parts, "")
	fmt.Fprintln(os.Stdout, s)
}

// paragraphs
func ReadPara() {
	if curIdx >= len(inputLines) {
		WsEofFlag = "Y"
		return
	}
	line := inputLines[curIdx]
	curIdx++
	if len(line) < 14 {
		line = line + strings.Repeat(" ", 14-len(line))
	} else if len(line) > 14 {
		line = line[:14]
	}
	CurRec.BrBranch = line[0:2]
	CurRec.BrAcct = line[2:6]
	CurRec.BrType = line[6:7]
	raw := line[7:14]
	cleaned := ""
	for _, ch := range raw {
		if ch >= '0' && ch <= '9' {
			cleaned += string(ch)
		} else {
			cleaned += "0"
		}
	}
	n, _ := strconv.ParseInt(cleaned, 10, 64)
	CurRec.BrAmt = decimal.New(n, -2)
}

func PostPara() {
	WsAmtEd = formatAmtEd(CurRec.BrAmt)
	switch CurRec.BrType {
	case "D":
		WsBal = storeField(WsBal.Add(CurRec.BrAmt), 7, 2)
		displayConcat(CurRec.BrAcct, " D ", WsAmtEd)
	case "C":
		WsBal = storeField(WsBal.Sub(CurRec.BrAmt), 7, 2)
		displayConcat(CurRec.BrAcct, " C ", WsAmtEd)
	default:
		WsSkipped = (WsSkipped + 1) % 100
		displayConcat(CurRec.BrAcct, " ? SKIPPED")
	}
}

func AcctBreakPara() {
	WsBalEd = formatBalEd(WsBal)
	displayConcat("  ACCOUNT ", WsPrevAcct, " BALANCE:", WsBalEd)
	WsBranchTot = storeField(WsBranchTot.Add(WsBal), 9, 2)
	WsBal = decimal.Zero
}

func BranchBreakPara() {
	WsTotEd = formatTotEd(WsBranchTot)
	displayConcat(" BRANCH ", WsPrevBranch, " TOTAL:", WsTotEd)
	WsGrandTot = storeField(WsGrandTot.Add(WsBranchTot), 9, 2)
	WsBranchTot = decimal.Zero
}

func GrandPara() {
	WsTotEd = formatTotEd(WsGrandTot)
	displayConcat("GRAND TOTAL:", WsTotEd)
	skippedStr := fmt.Sprintf("%02d", WsSkipped)
	displayConcat("SKIPPED: ", skippedStr)
}

func ProcessPara() {
	if FirstRecord() {
		WsPrevBranch = CurRec.BrBranch
		WsPrevAcct = CurRec.BrAcct
		WsFirstFlag = "N"
	} else {
		if CurRec.BrBranch != WsPrevBranch {
			AcctBreakPara()
			BranchBreakPara()
			WsPrevBranch = CurRec.BrBranch
			WsPrevAcct = CurRec.BrAcct
		} else {
			if CurRec.BrAcct != WsPrevAcct {
				AcctBreakPara()
				WsPrevAcct = CurRec.BrAcct
			}
		}
	}
	PostPara()
	ReadPara()
}

func MainPara() {
	data, err := os.ReadFile("input.dat")
	if err != nil {
		fmt.Fprintf(os.Stderr, "failed to open input.dat: %v\n", err)
		os.Exit(1)
	}
	content := string(data)
	rawSplit := strings.Split(content, "\n")
	inputLines = make([]string, 0, len(rawSplit))
	for i, lr := range rawSplit {
		if strings.HasSuffix(lr, "\r") {
			lr = strings.TrimSuffix(lr, "\r")
		}
		if i == len(rawSplit)-1 && lr == "" && len(content) > 0 && content[len(content)-1] == '\n' {
			continue
		}
		inputLines = append(inputLines, lr)
	}
	curIdx = 0
	ReadPara()
	for !InputDone() {
		ProcessPara()
	}
	if !FirstRecord() {
		AcctBreakPara()
		BranchBreakPara()
	}
	GrandPara()
}

func main() {
	MainPara()
}
